    if isinstance(value, dict):
        parts = [_flatten(value[key]) for key in sorted(value)]
        return np.concatenate(parts) if parts else np.empty(0, dtype=float)
    if isinstance(value, (list, tuple)):
        parts = [_flatten(item) for item in value]
        return np.concatenate(parts) if parts else np.empty(0, dtype=float)
    return np.asarray(value, dtype=float).ravel()

def project(value):
    raw = _flatten(value)
    missing = np.isnan(raw)
    return np.concatenate((np.where(missing, 0.0, raw), missing.astype(float)))

def expect_value_error(fn, *args):
    try:
        fn(*args)
    except ValueError:
        return np.array([1.0])
    return np.array([0.0])

def expect_runtime_error(fn, *args):
    try:
        fn(*args)
    except RuntimeError:
        return np.array([1.0])
    return np.array([0.0])

def leslie(fertility, survival):
    matrix = np.zeros((len(fertility), len(fertility)))
    matrix[0, :] = fertility
    for index, probability in enumerate(survival):
        matrix[index + 1, index] = probability
    return matrix

F = np.array([0.0, 0.4, 1.0, 1.4, 1.6, 1.8, 1.6])
P = np.array([0.60, 0.72, 0.78, 0.76, 0.70, 0.50])

def resolved(fertility, survival, subdivisions):
    classes = len(fertility)
    matrix = np.zeros((classes * subdivisions, classes * subdivisions))
    for age_class in range(1, classes + 1):
        matrix[0, age_class * subdivisions - 1] = fertility[age_class - 1]
    for index in range(1, classes * subdivisions):
        matrix[index, index - 1] = survival[index // subdivisions - 1] if index % subdivisions == 0 else 1.0
    return matrix
assert np.allclose(expect_value_error(interstage_flow_aggregate, leslie(F, P), 2, 1), target)

